type FormatMessageFn = (
  descriptor: { id: string },
  values?: Record<string, string>,
) => string;

type PhiSectionKey = 'totalPhi' | 'phiPerformance';

const SECTION_I18N_IDS: Record<
  PhiSectionKey,
  { global: string; scoped: string }
> = {
  totalPhi: {
    global: 'PortfolioBrand.PortfolioHealthIndex.Overview.totalPhi.globalTitle',
    scoped: 'PortfolioBrand.PortfolioHealthIndex.Overview.totalPhi.scopedTitle',
  },
  phiPerformance: {
    global:
      'PortfolioBrand.PortfolioHealthIndex.Overview.phiPerformance.globalTitle',
    scoped:
      'PortfolioBrand.PortfolioHealthIndex.Overview.phiPerformance.scopedTitle',
  },
};

export function getPhiScopeSectionTitle(
  formatMessage: FormatMessageFn,
  section: PhiSectionKey,
  countryScope?: string,
): string {
  const scope = countryScope?.trim();
  const ids = SECTION_I18N_IDS[section];

  if (!scope) {
    return formatMessage({ id: ids.global });
  }

  return formatMessage({ id: ids.scoped }, { scope });
}
